package com.xianqi.phonevalidation;
import org.junit.Test;
import static org.junit.Assert.*;
import com.google.zxing.*;
import com.google.zxing.common.BitMatrix;
import java.nio.ByteBuffer;
public class BarcodeDecoderTest {
    @Test public void decodesFull19DigitSkuAndRotatedFrames()throws Exception{String sku="0012345678901988220";int w=640,h=480;BitMatrix bars=new com.google.zxing.oned.Code128Writer().encode(sku,BarcodeFormat.CODE_128,w,180);byte[] y=new byte[w*h];java.util.Arrays.fill(y,(byte)255);for(int row=0;row<180;row++)for(int x=0;x<w;x++)if(bars.get(x,row))y[(row+150)*w+x]=0;BarcodeDecoder decoder=new BarcodeDecoder();assertEquals(sku,decoder.decode(y,w,h).getText());byte[] rotated=new byte[y.length];for(int row=0;row<h;row++)for(int x=0;x<w;x++)rotated[x*h+h-1-row]=y[row*w+x];assertEquals(sku,decoder.decode(rotated,h,w).getText());}
    @Test public void decodesTextureBitmapPixelsWithoutLosingLongSku()throws Exception{String sku="0012345678901988220";int w=1000,h=700;BitMatrix bars=new com.google.zxing.oned.Code128Writer().encode(sku,BarcodeFormat.CODE_128,w,400);int[] pixels=new int[w*h];java.util.Arrays.fill(pixels,0xffffffff);for(int y=0;y<400;y++)for(int x=0;x<w;x++)if(bars.get(x,y))pixels[(y+150)*w+x]=0xff000000;assertEquals(sku,new BarcodeDecoder().decode(BarcodeDecoder.rgb(pixels,w,h),w,h).getText());}
    @Test public void rgbUsesLuminanceAndRejectsInvalidBitmapBounds(){assertArrayEquals(new byte[]{0,(byte)255,77,(byte)149,29},BarcodeDecoder.rgb(new int[]{0xff000000,0xffffffff,0xffff0000,0xff00ff00,0xff0000ff},5,1));for(int[] shape:new int[][]{{0,1},{1,0},{3,2},{1281,961},{Integer.MAX_VALUE,2}})try{BarcodeDecoder.rgb(new int[5],shape[0],shape[1]);fail("Invalid bitmap accepted");}catch(IllegalArgumentException expected){}}
    @Test public void rawHighResolutionPaddedYuvFramesDecodeAtEveryRotation()throws Exception{String sku="0012345678901988220";int w=1280,h=960,stride=w+32;BitMatrix bars=new com.google.zxing.oned.Code128Writer().encode(sku,BarcodeFormat.CODE_128,w-160,260);ByteBuffer buffer=ByteBuffer.allocateDirect(stride*h);for(int i=0;i<buffer.capacity();i++)buffer.put(i,(byte)210);for(int y=0;y<260;y++)for(int x=0;x<w-160;x++)if(bars.get(x,y))buffer.put((y+350)*stride+x+80,(byte)65);byte[] data=BarcodeDecoder.luminance(buffer.asReadOnlyBuffer(),stride,1,w,h);BarcodeDecoder reader=new BarcodeDecoder();for(int turn=0;turn<4;turn++){assertEquals(sku,reader.decode(data,w,h).getText());byte[] next=new byte[data.length];for(int y=0;y<h;y++)for(int x=0;x<w;x++)next[x*h+h-1-y]=data[y*w+x];data=next;int swap=w;w=h;h=swap;}}
    @Test public void invertedBarcodeAlsoDecodes()throws Exception{String sku="2110000000000123457";int w=1280,h=720;BitMatrix bars=new com.google.zxing.oned.Code128Writer().encode(sku,BarcodeFormat.CODE_128,w-160,260);byte[] data=new byte[w*h];for(int y=0;y<260;y++)for(int x=0;x<w-160;x++)if(bars.get(x,y))data[(y+230)*w+x+80]=(byte)255;assertEquals(sku,new BarcodeDecoder().decode(data,w,h).getText());}
    @Test public void handlesCameraRowPaddingAndPixelStride(){assertArrayEquals(new byte[]{1,2,3,4,5,6},BarcodeDecoder.luminance(ByteBuffer.wrap(new byte[]{1,2,3,9,9,4,5,6}),5,1,3,2));assertArrayEquals(new byte[]{1,2,3,4},BarcodeDecoder.luminance(ByteBuffer.wrap(new byte[]{1,9,2,9,4,3,9,4}),5,2,2,2));}
    @Test public void bulkCopiesDirectReadOnlyCameraBuffersWithoutMovingTheInput(){ByteBuffer bytes=ByteBuffer.allocateDirect(14);bytes.position(2);bytes.put(new byte[]{1,2,3,99,99,4,5,6,99,99,7,8});bytes.position(2);bytes.limit(10);ByteBuffer input=bytes.asReadOnlyBuffer();assertArrayEquals(new byte[]{1,2,3,4,5,6},BarcodeDecoder.luminance(input,5,1,3,2));assertEquals(2,input.position());assertEquals(10,input.limit());}
    @Test public void rejectsTruncatedOrUnboundedCameraFrames(){for(int[] shape:new int[][]{{5,1,3,3},{0,1,3,2},{5,0,3,2},{5,1,0,2},{5,1,1281,961}})try{BarcodeDecoder.luminance(ByteBuffer.allocateDirect(8),shape[0],shape[1],shape[2],shape[3]);fail("Invalid camera frame accepted");}catch(IllegalArgumentException expected){}}
    @Test public void scanQueryPreservesIdentifiersAndUsesActualBarcodeType(){assertEquals("SKU:0012345678901988220",BarcodeDecoder.query("0012345678901988220","CODE_128"));assertEquals("条码:0123456789012",BarcodeDecoder.query("0123456789012","EAN_13"));assertEquals("库位:A10-1-1",BarcodeDecoder.query("a10-1-1","CODE_128"));assertEquals("SKU:abc_DEF",BarcodeDecoder.query("abc_DEF","CODE_128"));try{BarcodeDecoder.query("https://example.com","QR_CODE");fail();}catch(IllegalArgumentException expected){}}
}
